const tabId = 248688717;
// Let's inspect the visible comparison sections and differences
const comparisonData = await browserjs(tabId, () => {
  const sections = Array.from(document.querySelectorAll('section, .accordion-item, .sds-accordion-item, tr')).map(el => el.textContent.trim()).filter(Boolean);

  // Extract tables / differences
  const tables = Array.from(document.querySelectorAll('table')).map(table => {
    const rows = Array.from(table.querySelectorAll('tr')).map(tr => {
      const ths = Array.from(tr.querySelectorAll('th')).map(th => th.textContent.trim());
      const tds = Array.from(tr.querySelectorAll('td')).map(td => td.textContent.trim());
      return { ths, tds, isHidden: tr.offsetParent === null || tr.classList.contains('hidden') || tr.style.display === 'none' };
    }).filter(r => !r.isHidden);
    return rows;
  });

  return {
    tables: tables.filter(t => t.length > 0)
  };
});

console.log("Extracted visible comparison tables count:", comparisonData.tables.length);
console.log("Comparison data sample:", JSON.stringify(comparisonData.tables.slice(0, 3), null, 2));

