const comparisonReport = await browserjs(tabId, () => {
  const cars = Array.from(document.querySelectorAll('.compare-page-card, .vehicle-card, [data-qa*="vehicle"]')).map(el => el.textContent.trim().replace(/\s+/g, ' '));

  // Let's get the car names from the header
  const carHeaders = Array.from(document.querySelectorAll('a[href*="/research/audi/"]')).map(a => a.textContent.trim());

  // Let's extract all comparison rows from all sections
  const sections = [];
  const accordions = Array.from(document.querySelectorAll('fuse-accordion'));

  for (const acc of accordions) {
    const sectionTitle = acc.querySelector('h2, h3, [slot="headline"]')?.textContent.trim();
    const rows = [];
    const trs = Array.from(acc.querySelectorAll('tr'));
    for (const tr of trs) {
      const tds = Array.from(tr.querySelectorAll('td')).map(td => td.textContent.trim().replace(/\s+/g, ' '));
      if (tds.length >= 2) {
        // First car value, second car value, label
        // Usually the label is at the end or in a th or td
        rows.push({
          car1Val: tds[0],
          car2Val: tds[1],
          label: tds[2] || tds[1] || ''
        });
      }
    }
    sections.push({ sectionTitle, rows });
  }

  return {
    carHeaders,
    sections: sections.filter(s => s.rows.length > 0)
  };
});

