  for (const acc of accordions) {
    const title = acc.querySelector('h2, h3, [slot="headline"]')?.textContent.trim() || 'Unknown';
    const rows = Array.from(acc.querySelectorAll('tr'));
    const sectionDiffs = [];

    for (const tr of rows) {
      // In Cars.com compare table:
      // The cells contain text and a label. Let's extract the exact DOM structure inside each cell
      const tds = Array.from(tr.querySelectorAll('td'));
      if (tds.length >= 2) {
        const text1 = tds[0].innerText.trim();
        const text2 = tds[1].innerText.trim();
        sectionDiffs.push({ text1, text2 });
      }
    }
    if (sectionDiffs.length > 0) {
      results.push({ title, rows: sectionDiffs });
    }
  }

  return results;
});

