const allDifferences = await browserjs(tabId, () => {
  const accordions = Array.from(document.querySelectorAll('fuse-accordion'));
  const differences = [];

  for (const acc of accordions) {
    const category = acc.querySelector('h2, h3, [slot="headline"]')?.textContent.trim() || 'Unknown';
    const trs = Array.from(acc.querySelectorAll('tr'));

    for (const tr of trs) {
      const tds = Array.from(tr.querySelectorAll('td'));
      if (tds.length >= 2) {
        // Find label
        const labelEl = tr.querySelector('.cell-label, th, [data-qa*="label"]') || tds[0].querySelector('.cell-label') || tds[tds.length - 1];

        // Let's get raw text of td[0] and td[1]
        // Usually td[0] has value then label, td[1] has value then label
        const val1 = tds[0].childNodes[0]?.textContent?.trim() || tds[0].innerText.split('\n')[0].trim();
        const val2 = tds[1].childNodes[0]?.textContent?.trim() || tds[1].innerText.split('\n')[0].trim();

        // Let's also extract full text to get the metric name
        const full1 = tds[0].innerText.trim();
        const full2 = tds[1].innerText.trim();

        // Extract metric name by removing val1 from full1
        let metric = full1.replace(val1, '').trim();
        if (!metric) {
          metric = tds[tds.length - 1]?.innerText.trim() || 'Attribute';
        }

        if (val1 !== val2) {
          differences.push({
            category,
            metric,
            audiA7: val1,
            audiA6: val2
          });
        }
      }
    }
  }

  return differences;
});

