const tabId = 248688717;

const allDiffsClean = await browserjs(tabId, () => {
  const accordions = Array.from(document.querySelectorAll('fuse-accordion'));
  const diffs = [];

  for (const acc of accordions) {
    const category = acc.querySelector('h2, h3, [slot="headline"]')?.textContent.trim() || 'Unknown';
    const trs = Array.from(acc.querySelectorAll('tr'));

    for (const tr of trs) {
      const tds = Array.from(tr.querySelectorAll('td'));
      if (tds.length >= 2) {
        // Look at how Cars.com renders table cells
        // e.g. td[0] has two spans or text nodes: value and label
        const getValAndLabel = (td) => {
          const lines = td.innerText.trim().split('\n').map(s => s.trim()).filter(Boolean);
          if (lines.length >= 2) {
            return { val: lines[0], label: lines.slice(1).join(' ') };
          } else if (lines.length === 1) {
            // maybe "3.0 L/183 Displacement"
            // Let's check child elements
            const children = Array.from(td.children);
            if (children.length >= 2) {
              return { val: children[0].textContent.trim(), label: children[1].textContent.trim() };
            }
            return { val: lines[0], label: '' };
          }
          return { val: '', label: '' };
        };

        const car1 = getValAndLabel(tds[0]);
        const car2 = getValAndLabel(tds[1]);

        if (car1.val && car2.val && car1.val !== car2.val) {
          diffs.push({
            category,
            label: car1.label || car2.label,
            audiA7_2023: car1.val,
            audiA6_2023: car2.val
          });
        }
      }
    }
  }

  return diffs;
});

console.log("All clean differences count:", allDiffsClean.length);
